window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f3629817f54c8d5c"]={"versions": [{"id": "FIG-f3629817f54c8d5c", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Blueprinting-Mechanismus für Port-Prototypen im AUTOSAR-Standardization-Template (TPS Standardization Template). Das Diagramm modelliert die strukturellen Zusammenhänge zwischen der Blueprint-Definition eines PortPrototype und den zugehörigen Schnittstellen sowie Initialwertdefinitionen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>PortPrototypeBlueprint</code> (Stereotypen: <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpStructureElement</code>): Zentrale Blueprint-Klasse für Port-Prototypen.\n<ul class=\"fig-list\"><li>Besitzt eine gerichtete Assoziation <code>+interface</code> mit Multiplizität <code>1</code> auf <code>PortInterface</code>.\n</li><li>Besitzt eine Komposition <code>+initValue</code> mit Multiplizität <code>0..*</code> auf <code>PortPrototypeBlueprintInitValue</code>.\n</li></ul>\n</li><li><code>PortInterface</code> (Stereotypen: <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>): Die durch den Blueprint referenzierte Schnittstelle.\n<ul class=\"fig-list\"><li>Attribute:\n<ul class=\"fig-list\"><li><code>+ isService: Boolean</code>\n</li><li><code>+ serviceKind: ServiceProviderEnum [0..1]</code>\n</li></ul>\n</li></ul>\n</li><li><code>PortPrototypeBlueprintInitValue</code>: Assoziationselement zur Festlegung von Initialwerten im Blueprint.\n<ul class=\"fig-list\"><li>Besitzt eine gerichtete Assoziation <code>+dataPrototype</code> mit Multiplizität <code>1</code> auf <code>AutosarDataPrototype</code> (Stereotyp: <code>DataPrototype</code>).\n</li><li>Besitzt eine Komposition <code>+value</code> mit Multiplizität <code>1</code> auf <code>ValueSpecification</code>.\n</li></ul>\n</li><li><code>AutosarDataPrototype</code> (Stereotyp: <code>DataPrototype</code>): Konkreter Datenprototyp innerhalb der Schnittstelle.\n</li><li><code>ValueSpecification</code>: Spezifikation des konkreten Initialwerts.\n<ul class=\"fig-list\"><li>Attribut:\n<ul class=\"fig-list\"><li><code>+ shortLabel: Identifier [0..1]</code>\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm stellt das Schaubild keine dynamischen Interaktionen, Nachrichtenaustausche oder zeitlichen Abläufe dar. Es definiert deklarative Strukturbeziehungen und Multiplizitäten zur blueprint-basierten Modellierung von Port-Prototypen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler und Spezifikationsanwender müssen beachten:</p>\n<ul class=\"fig-list\"><li>Jeder <code>PortPrototypeBlueprint</code> muss genau eine <code>PortInterface</code> referenzieren (<code>1</code>).\n</li><li>Initialwerte über <code>PortPrototypeBlueprintInitValue</code> sind optional und mehrfach möglich (<code>0..*</code>), verlangen aber pro Eintrag zwingend genau einen <code>AutosarDataPrototype</code> (<code>1</code>) und genau eine <code>ValueSpecification</code> (<code>1</code>).\n</li><li>Das Attribut <code>isService</code> an <code>PortInterface</code> ist obligatorisch (<code>Boolean</code>), während <code>serviceKind</code> optional vorliegen kann (<code>[0..1]</code>).\n</li><li>Bei <code>ValueSpecification</code> ist die Angabe von <code>shortLabel</code> optional (<code>[0..1]</code>).\n</li></ul>"}, {"id": "FIG-6cb9c2d4dd66c3a7", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Blueprinting-Mechanismus für Port-Prototypen im AUTOSAR-Standardization-Template (TPS Standardization Template). Das Diagramm modelliert die strukturellen Zusammenhänge zwischen der Blueprint-Definition eines PortPrototype und den zugehörigen Schnittstellen sowie Initialwertdefinitionen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>PortPrototypeBlueprint</code> (Stereotypen: <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpStructureElement</code>): Zentrale Blueprint-Klasse für Port-Prototypen.\n<ul class=\"fig-list\"><li>Besitzt eine gerichtete Assoziation <code>+interface</code> mit Multiplizität <code>1</code> auf <code>PortInterface</code>.\n</li><li>Besitzt eine Komposition <code>+initValue</code> mit Multiplizität <code>0..*</code> auf <code>PortPrototypeBlueprintInitValue</code>.\n</li></ul>\n</li><li><code>PortInterface</code> (Stereotypen: <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>): Die durch den Blueprint referenzierte Schnittstelle.\n<ul class=\"fig-list\"><li>Attribute:\n<ul class=\"fig-list\"><li><code>+ isService: Boolean</code>\n</li><li><code>+ serviceKind: ServiceProviderEnum [0..1]</code>\n</li></ul>\n</li></ul>\n</li><li><code>PortPrototypeBlueprintInitValue</code>: Assoziationselement zur Festlegung von Initialwerten im Blueprint.\n<ul class=\"fig-list\"><li>Besitzt eine gerichtete Assoziation <code>+dataPrototype</code> mit Multiplizität <code>1</code> auf <code>AutosarDataPrototype</code> (Stereotyp: <code>DataPrototype</code>).\n</li><li>Besitzt eine Komposition <code>+value</code> mit Multiplizität <code>1</code> auf <code>ValueSpecification</code>.\n</li></ul>\n</li><li><code>AutosarDataPrototype</code> (Stereotyp: <code>DataPrototype</code>): Konkreter Datenprototyp innerhalb der Schnittstelle.\n</li><li><code>ValueSpecification</code>: Spezifikation des konkreten Initialwerts.\n<ul class=\"fig-list\"><li>Attribut:\n<ul class=\"fig-list\"><li><code>+ shortLabel: Identifier [0..1]</code>\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm stellt das Schaubild keine dynamischen Interaktionen, Nachrichtenaustausche oder zeitlichen Abläufe dar. Es definiert deklarative Strukturbeziehungen und Multiplizitäten zur blueprint-basierten Modellierung von Port-Prototypen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler und Spezifikationsanwender müssen beachten:</p>\n<ul class=\"fig-list\"><li>Jeder <code>PortPrototypeBlueprint</code> muss genau eine <code>PortInterface</code> referenzieren (<code>1</code>).\n</li><li>Initialwerte über <code>PortPrototypeBlueprintInitValue</code> sind optional und mehrfach möglich (<code>0..*</code>), verlangen aber pro Eintrag zwingend genau einen <code>AutosarDataPrototype</code> (<code>1</code>) und genau eine <code>ValueSpecification</code> (<code>1</code>).\n</li><li>Das Attribut <code>isService</code> an <code>PortInterface</code> ist obligatorisch (<code>Boolean</code>), während <code>serviceKind</code> optional vorliegen kann (<code>[0..1]</code>).\n</li><li>Bei <code>ValueSpecification</code> ist die Angabe von <code>shortLabel</code> optional (<code>[0..1]</code>).\n</li></ul>"}, {"id": "FIG-e43a8cf6b2ccfae3", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Blueprinting-Mechanismus für Port-Prototypen im AUTOSAR-Standardization-Template (TPS Standardization Template). Das Diagramm modelliert die strukturellen Zusammenhänge zwischen der Blueprint-Definition eines PortPrototype und den zugehörigen Schnittstellen sowie Initialwertdefinitionen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>PortPrototypeBlueprint</code> (Stereotypen: <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpStructureElement</code>): Zentrale Blueprint-Klasse für Port-Prototypen.\n<ul class=\"fig-list\"><li>Besitzt eine gerichtete Assoziation <code>+interface</code> mit Multiplizität <code>1</code> auf <code>PortInterface</code>.\n</li><li>Besitzt eine Komposition <code>+initValue</code> mit Multiplizität <code>0..*</code> auf <code>PortPrototypeBlueprintInitValue</code>.\n</li><li>Besitzt eine Komposition <code>+providedComSpec</code> mit Multiplizität <code>0..*</code> auf <code>PPortComSpec</code>.\n</li><li>Besitzt eine Komposition <code>+requiredComSpec</code> mit Multiplizität <code>0..*</code> auf <code>RPortComSpec</code>.\n</li></ul>\n</li><li><code>PortInterface</code> (Stereotypen: <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>): Die durch den Blueprint referenzierte Schnittstelle.\n<ul class=\"fig-list\"><li>Attribute:\n<ul class=\"fig-list\"><li><code>+ isService :Boolean</code>\n</li><li><code>+ serviceKind :ServiceProviderEnum [0..1]</code>\n</li></ul>\n</li></ul>\n</li><li><code>PortPrototypeBlueprintInitValue</code>: Assoziationselement zur Festlegung von Initialwerten im Blueprint.\n<ul class=\"fig-list\"><li>Besitzt eine gerichtete Assoziation <code>+dataPrototype</code> mit Multiplizität <code>1</code> auf <code>AutosarDataPrototype</code> (Stereotyp: <code>DataPrototype</code>).\n</li><li>Besitzt eine Komposition <code>+value</code> mit Multiplizität <code>1</code> auf <code>ValueSpecification</code>.\n</li></ul>\n</li><li><code>AutosarDataPrototype</code> (Stereotyp: <code>DataPrototype</code>): Konkreter Datenprototyp innerhalb der Schnittstelle.\n</li><li><code>ValueSpecification</code>: Spezifikation des konkreten Initialwerts.\n<ul class=\"fig-list\"><li>Attribut:\n<ul class=\"fig-list\"><li><code>+ shortLabel :Identifier [0..1]</code>\n</li></ul>\n</li></ul>\n</li><li><code>PPortComSpec</code>: Kommunikationsspezifikation für bereitgestellte Ports (Provided Ports).\n</li><li><code>RPortComSpec</code>: Kommunikationsspezifikation für angeforderte Ports (Required Ports).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm stellt das Schaubild keine dynamischen Interaktionen, Nachrichtenaustausche oder zeitlichen Abläufe dar. Es definiert deklarative Strukturbeziehungen und Multiplizitäten zur blueprint-basierten Modellierung von Port-Prototypen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler und Spezifikationsanwender müssen beachten:</p>\n<ul class=\"fig-list\"><li>Jeder <code>PortPrototypeBlueprint</code> muss genau eine <code>PortInterface</code> referenzieren (<code>1</code>).\n</li><li>Kommunikationsspezifikationen können über <code>providedComSpec</code> (<code>PPortComSpec</code>) und <code>requiredComSpec</code> (<code>RPortComSpec</code>) jeweils mit der Multiplizität <code>0..*</code> als feste Bestandteile des Blueprints definiert werden.\n</li><li>Initialwerte über <code>PortPrototypeBlueprintInitValue</code> sind optional und mehrfach möglich (<code>0..*</code>), verlangen aber pro Eintrag zwingend genau einen <code>AutosarDataPrototype</code> (<code>1</code>) und genau eine <code>ValueSpecification</code> (<code>1</code>).\n</li><li>Das Attribut <code>isService</code> an <code>PortInterface</code> ist obligatorisch (<code>Boolean</code>), während <code>serviceKind</code> optional vorliegen kann (<code>[0..1]</code>).\n</li><li>Bei <code>ValueSpecification</code> ist die Angabe von <code>shortLabel</code> optional (<code>[0..1]</code>).\n</li></ul>"}, {"id": "FIG-bd946c9820de66c3", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Blueprinting-Mechanismus für Port-Prototypen im AUTOSAR-Standardization-Template (TPS Standardization Template). Das Diagramm modelliert die strukturellen Zusammenhänge zwischen der Blueprint-Definition eines PortPrototype und den zugehörigen Schnittstellen sowie Initialwertdefinitionen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>PortPrototypeBlueprint</code> (Stereotypen: <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpStructureElement</code>): Zentrale Blueprint-Klasse für Port-Prototypen.\n<ul class=\"fig-list\"><li>Besitzt eine gerichtete Assoziation <code>+interface</code> mit Multiplizität <code>1</code> auf <code>PortInterface</code>.\n</li><li>Besitzt eine Komposition <code>+initValue</code> mit Multiplizität <code>0..*</code> auf <code>PortPrototypeBlueprintInitValue</code>.\n</li><li>Besitzt eine Komposition <code>+providedComSpec</code> mit Multiplizität <code>0..*</code> auf <code>PPortComSpec</code>.\n</li><li>Besitzt eine Komposition <code>+requiredComSpec</code> mit Multiplizität <code>0..*</code> auf <code>RPortComSpec</code>.\n</li></ul>\n</li><li><code>PortInterface</code> (Stereotypen: <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>): Die durch den Blueprint referenzierte Schnittstelle.\n<ul class=\"fig-list\"><li>Attribute:\n<ul class=\"fig-list\"><li><code>+ isService :Boolean</code>\n</li><li><code>+ serviceKind :ServiceProviderEnum [0..1]</code>\n</li></ul>\n</li></ul>\n</li><li><code>PortPrototypeBlueprintInitValue</code>: Assoziationselement zur Festlegung von Initialwerten im Blueprint.\n<ul class=\"fig-list\"><li>Besitzt eine gerichtete Assoziation <code>+dataPrototype</code> mit Multiplizität <code>1</code> auf <code>AutosarDataPrototype</code> (Stereotyp: <code>DataPrototype</code>).\n</li><li>Besitzt eine Komposition <code>+value</code> mit Multiplizität <code>1</code> auf <code>ValueSpecification</code>.\n</li></ul>\n</li><li><code>AutosarDataPrototype</code> (Stereotyp: <code>DataPrototype</code>): Konkreter Datenprototyp innerhalb der Schnittstelle.\n</li><li><code>ValueSpecification</code>: Spezifikation des konkreten Initialwerts.\n<ul class=\"fig-list\"><li>Attribut:\n<ul class=\"fig-list\"><li><code>+ shortLabel :Identifier [0..1]</code>\n</li></ul>\n</li></ul>\n</li><li><code>PPortComSpec</code>: Kommunikationsspezifikation für bereitgestellte Ports (Provided Ports).\n</li><li><code>RPortComSpec</code>: Kommunikationsspezifikation für angeforderte Ports (Required Ports).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm stellt das Schaubild keine dynamischen Interaktionen, Nachrichtenaustausche oder zeitlichen Abläufe dar. Es definiert deklarative Strukturbeziehungen und Multiplizitäten zur blueprint-basierten Modellierung von Port-Prototypen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler und Spezifikationsanwender müssen beachten:</p>\n<ul class=\"fig-list\"><li>Jeder <code>PortPrototypeBlueprint</code> muss genau eine <code>PortInterface</code> referenzieren (<code>1</code>).\n</li><li>Kommunikationsspezifikationen können über <code>providedComSpec</code> (<code>PPortComSpec</code>) und <code>requiredComSpec</code> (<code>RPortComSpec</code>) jeweils mit der Multiplizität <code>0..*</code> als feste Bestandteile des Blueprints definiert werden.\n</li><li>Initialwerte über <code>PortPrototypeBlueprintInitValue</code> sind optional und mehrfach möglich (<code>0..*</code>), verlangen aber pro Eintrag zwingend genau einen <code>AutosarDataPrototype</code> (<code>1</code>) und genau eine <code>ValueSpecification</code> (<code>1</code>).\n</li><li>Das Attribut <code>isService</code> an <code>PortInterface</code> ist obligatorisch (<code>Boolean</code>), während <code>serviceKind</code> optional vorliegen kann (<code>[0..1]</code>).\n</li><li>Bei <code>ValueSpecification</code> ist die Angabe von <code>shortLabel</code> optional (<code>[0..1]</code>).\n</li></ul>"}, {"id": "FIG-f5b4674b34e35019", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Blueprinting-Mechanismus für Port-Prototypen im AUTOSAR-Standardization-Template (TPS Standardization Template). Das Diagramm modelliert die strukturellen Zusammenhänge zwischen der Blueprint-Definition eines PortPrototype und den zugehörigen Schnittstellen sowie Initialwertdefinitionen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>PortPrototypeBlueprint</code> (Stereotypen: <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpStructureElement</code>): Zentrale Blueprint-Klasse für Port-Prototypen.\n<ul class=\"fig-list\"><li>Besitzt eine gerichtete Assoziation <code>+interface</code> mit Multiplizität <code>1</code> auf <code>PortInterface</code>.\n</li><li>Besitzt eine Komposition <code>+initValue</code> mit Multiplizität <code>0..*</code> auf <code>PortPrototypeBlueprintInitValue</code>.\n</li><li>Besitzt eine Komposition <code>+providedComSpec</code> mit Multiplizität <code>0..*</code> auf <code>PPortComSpec</code>.\n</li><li>Besitzt eine Komposition <code>+requiredComSpec</code> mit Multiplizität <code>0..*</code> auf <code>RPortComSpec</code>.\n</li></ul>\n</li><li><code>PortInterface</code> (Stereotypen: <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>): Die durch den Blueprint referenzierte Schnittstelle.\n<ul class=\"fig-list\"><li>Attribute:\n<ul class=\"fig-list\"><li><code>+ isService: Boolean [0..1]</code>\n</li><li><code>+ serviceKind: ServiceProviderEnum [0..1]</code>\n</li></ul>\n</li></ul>\n</li><li><code>PortPrototypeBlueprintInitValue</code>: Assoziationselement zur Festlegung von Initialwerten im Blueprint.\n<ul class=\"fig-list\"><li>Besitzt eine gerichtete Assoziation <code>+dataPrototype</code> mit Multiplizität <code>1</code> auf <code>AutosarDataPrototype</code> (Stereotyp: <code>DataPrototype</code>).\n</li><li>Besitzt eine Komposition <code>+value</code> mit Multiplizität <code>1</code> auf <code>ValueSpecification</code>.\n</li></ul>\n</li><li><code>AutosarDataPrototype</code> (Stereotyp: <code>DataPrototype</code>): Konkreter Datenprototyp innerhalb der Schnittstelle.\n</li><li><code>ValueSpecification</code>: Spezifikation des konkreten Initialwerts.\n<ul class=\"fig-list\"><li>Attribut:\n<ul class=\"fig-list\"><li><code>+ shortLabel: Identifier [0..1]</code>\n</li></ul>\n</li></ul>\n</li><li><code>PPortComSpec</code>: Kommunikationsspezifikation für bereitgestellte Ports (Provided Ports).\n</li><li><code>RPortComSpec</code>: Kommunikationsspezifikation für angeforderte Ports (Required Ports).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm stellt das Schaubild keine dynamischen Interaktionen, Nachrichtenaustausche oder zeitlichen Abläufe dar. Es definiert deklarative Strukturbeziehungen und Multiplizitäten zur blueprint-basierten Modellierung von Port-Prototypen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler und Spezifikationsanwender müssen beachten:</p>\n<ul class=\"fig-list\"><li>Jeder <code>PortPrototypeBlueprint</code> muss genau eine <code>PortInterface</code> referenzieren (<code>1</code>).\n</li><li>Kommunikationsspezifikationen können über <code>providedComSpec</code> (<code>PPortComSpec</code>) und <code>requiredComSpec</code> (<code>RPortComSpec</code>) jeweils mit der Multiplizität <code>0..*</code> am Blueprint hinterlegt werden.\n</li><li>Initialwerte über <code>PortPrototypeBlueprintInitValue</code> sind optional und mehrfach möglich (<code>0..*</code>), verlangen aber pro Eintrag zwingend genau einen <code>AutosarDataPrototype</code> (<code>1</code>) und genau eine <code>ValueSpecification</code> (<code>1</code>).\n</li><li>An <code>PortInterface</code> sind sowohl <code>isService</code> als auch <code>serviceKind</code> optional mit der Kardinalität <code>[0..1]</code> modelliert.\n</li><li>Bei <code>ValueSpecification</code> ist die Angabe von <code>shortLabel</code> optional (<code>[0..1]</code>).\n</li></ul>"}, {"id": "FIG-8f1117ed7a7e220d", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Blueprinting-Mechanismus für Port-Prototypen im AUTOSAR-Standardization-Template (TPS Standardization Template). Das Diagramm modelliert die strukturellen Zusammenhänge zwischen der Blueprint-Definition eines PortPrototype und den zugehörigen Schnittstellen sowie Initialwertdefinitionen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>PortPrototypeBlueprint</code> (Stereotypen: <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpStructureElement</code>): Zentrale Blueprint-Klasse für Port-Prototypen.\n<ul class=\"fig-list\"><li>Besitzt eine gerichtete Assoziation <code>+interface</code> mit Multiplizität <code>1</code> auf <code>PortInterface</code>.\n</li><li>Besitzt eine Komposition <code>+initValue</code> mit Multiplizität <code>0..*</code> auf <code>PortPrototypeBlueprintInitValue</code>.\n</li><li>Besitzt eine Komposition <code>+providedComSpec</code> mit Multiplizität <code>0..*</code> auf <code>PPortComSpec</code>.\n</li><li>Besitzt eine Komposition <code>+requiredComSpec</code> mit Multiplizität <code>0..*</code> auf <code>RPortComSpec</code>.\n</li></ul>\n</li><li><code>PortInterface</code> (Stereotypen: <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>): Die durch den Blueprint referenzierte Schnittstelle.\n<ul class=\"fig-list\"><li>Attribute:\n<ul class=\"fig-list\"><li><code>+ isService: Boolean [0..1]</code>\n</li><li><code>+ serviceKind: ServiceProviderEnum [0..1]</code>\n</li></ul>\n</li></ul>\n</li><li><code>PortPrototypeBlueprintInitValue</code>: Assoziationselement zur Festlegung von Initialwerten im Blueprint.\n<ul class=\"fig-list\"><li>Besitzt eine gerichtete Assoziation <code>+dataPrototype</code> mit Multiplizität <code>1</code> auf <code>AutosarDataPrototype</code> (Stereotyp: <code>DataPrototype</code>).\n</li><li>Besitzt eine Komposition <code>+value</code> mit Multiplizität <code>1</code> auf <code>ValueSpecification</code>.\n</li></ul>\n</li><li><code>AutosarDataPrototype</code> (Stereotyp: <code>DataPrototype</code>): Konkreter Datenprototyp innerhalb der Schnittstelle.\n</li><li><code>ValueSpecification</code>: Spezifikation des konkreten Initialwerts.\n<ul class=\"fig-list\"><li>Attribut:\n<ul class=\"fig-list\"><li><code>+ shortLabel: Identifier [0..1]</code>\n</li></ul>\n</li></ul>\n</li><li><code>PPortComSpec</code>: Kommunikationsspezifikation für bereitgestellte Ports (Provided Ports).\n</li><li><code>RPortComSpec</code>: Kommunikationsspezifikation für angeforderte Ports (Required Ports).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm stellt das Schaubild keine dynamischen Interaktionen, Nachrichtenaustausche oder zeitlichen Abläufe dar. Es definiert deklarative Strukturbeziehungen und Multiplizitäten zur blueprint-basierten Modellierung von Port-Prototypen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler und Spezifikationsanwender müssen beachten:</p>\n<ul class=\"fig-list\"><li>Jeder <code>PortPrototypeBlueprint</code> muss genau eine <code>PortInterface</code> referenzieren (<code>1</code>).\n</li><li>Kommunikationsspezifikationen können über <code>providedComSpec</code> (<code>PPortComSpec</code>) und <code>requiredComSpec</code> (<code>RPortComSpec</code>) jeweils mit der Multiplizität <code>0..*</code> am Blueprint hinterlegt werden.\n</li><li>Initialwerte über <code>PortPrototypeBlueprintInitValue</code> sind optional und mehrfach möglich (<code>0..*</code>), verlangen aber pro Eintrag zwingend genau einen <code>AutosarDataPrototype</code> (<code>1</code>) und genau eine <code>ValueSpecification</code> (<code>1</code>).\n</li><li>An <code>PortInterface</code> sind sowohl <code>isService</code> als auch <code>serviceKind</code> optional mit der Kardinalität <code>[0..1]</code> modelliert.\n</li><li>Bei <code>ValueSpecification</code> ist die Angabe von <code>shortLabel</code> optional (<code>[0..1]</code>).\n</li></ul>"}], "trans": [{"from": "FIG-f3629817f54c8d5c", "to": "FIG-6cb9c2d4dd66c3a7", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><code>PortInterface</code>: Schreibweise der Attributtypen vereinheitlicht (<code>+ isService :Boolean</code> und <code>+ serviceKind :ServiceProviderEnum [0..1]</code> mit Leerzeichen vor dem Doppelpunkt).\n</li><li><code>ValueSpecification</code>: Schreibweise des Attributtyps vereinheitlicht (<code>+ shortLabel :Identifier [0..1]</code> mit Leerzeichen vor dem Doppelpunkt).\n</li></ul>"}, {"from": "FIG-6cb9c2d4dd66c3a7", "to": "FIG-e43a8cf6b2ccfae3", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>PortPrototypeBlueprint</code>: Kompositionen zu <code>PPortComSpec</code> (<code>+providedComSpec</code>, Kardinalität <code>0..*</code>) und <code>RPortComSpec</code> (<code>+requiredComSpec</code>, Kardinalität <code>0..*</code>) ergänzt.\n</li><li><code>PPortComSpec</code>: Neue Klasse als Ziel der Komposition <code>providedComSpec</code> eingefügt.\n</li><li><code>RPortComSpec</code>: Neue Klasse als Ziel der Komposition <code>requiredComSpec</code> eingefügt.\n</li></ul>"}, {"from": "FIG-e43a8cf6b2ccfae3", "to": "FIG-bd946c9820de66c3", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><code>PortInterface</code>: Schreibweise der Attribute angepasst (<code>+ isService: Boolean</code> und <code>+ serviceKind: ServiceProviderEnum [0..1]</code> ohne Leerzeichen vor dem Doppelpunkt).\n</li><li><code>ValueSpecification</code>: Schreibweise des Attributs angepasst (<code>+ shortLabel: Identifier [0..1]</code> ohne Leerzeichen vor dem Doppelpunkt).\n</li></ul>"}, {"from": "FIG-bd946c9820de66c3", "to": "FIG-f5b4674b34e35019", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>PortInterface</code>: Multiplizität des Attributs <code>isService</code> von obligatorisch (implizit <code>1</code>) auf optional geändert (<code>+ isService: Boolean [0..1]</code>).\n</li></ul>"}, {"from": "FIG-f5b4674b34e35019", "to": "FIG-8f1117ed7a7e220d", "fr": "R20-11", "tr": "R21-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><code>PortPrototypeBlueprint</code>: Die Assoziationslinien zu <code>PPortComSpec</code> (<code>+providedComSpec</code>) und <code>RPortComSpec</code> (<code>+requiredComSpec</code>) verlaufen nun schräg von zwei separaten Kompositionsrauten an der Seitenkante der Klasse statt orthogonal aus horizontalen Abzweigen; Kardinalitätsbeschriftungen <code>0..*</code> sind direkt an den Zielenden platziert.\n</li><li><code>RPortComSpec</code>: Kastenbreite vergrößert.\n</li></ul>"}]};
